using Cysharp.Threading.Tasks;using GamePush;namespace SaveLoadSystemNamespace {    public class GamePushStrategy : ISaveLoadStrategy {        private UniTaskCompletionSource<string> _getCompletionSource;        public  void Save(ISaveLoadObject saveObject) {            var jsonData = saveObject.GetSaveLoadData();            GP_Storage.Set(saveObject.objectKey, jsonData);        }        public async UniTask Load(ISaveLoadObject saveObject) {            _getCompletionSource = new UniTaskCompletionSource<string>();            GP_Storage.Get(saveObject.objectKey, OnDataLoaded);            var result = await _getCompletionSource.Task;            saveObject.RestoreValues(result);        }        private void OnDataLoaded(object s) {            _getCompletionSource.TrySetResult((string)s);        }    }}